import{_ as a,o as n,c as i,a3 as e}from"./chunks/framework.qCVWde4n.js";const u=JSON.parse('{"title":"安装 Mod 的三种方式","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/install-mod.md","filePath":"deploy/install-mod.md","lastUpdated":1791133906000}'),t={name:"deploy/install-mod.md"};function l(o,s,d,r,p,h){return n(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="安装-mod-的三种方式" tabindex="-1">安装 Mod 的三种方式 <a class="header-anchor" href="#安装-mod-的三种方式" aria-label="Permalink to &quot;安装 Mod 的三种方式&quot;">​</a></h1><p>不管 Mod 是谁做的、从哪来的，装进游戏都只有三条路。<strong>推荐第一条</strong>，最简单也最不容易出错。</p><h2 id="方式对比" tabindex="-1">方式对比 <a class="header-anchor" href="#方式对比" aria-label="Permalink to &quot;方式对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>需要电脑</th><th>需要找文件</th><th>适合谁</th></tr></thead><tbody><tr><td><strong>① 粘贴分享码</strong></td><td>不需要</td><td>不需要</td><td><strong>所有人（推荐）</strong></td></tr><tr><td>② 网页下载放进目录</td><td>不需要</td><td>需要</td><td>想批量装、或想要文件留底</td></tr><tr><td>③ 手动新建文件夹</td><td>不需要</td><td>需要</td><td>自己做 Mod、调试阶段</td></tr></tbody></table><hr><h2 id="方式-1-粘贴分享码-推荐" tabindex="-1">方式 ①：粘贴分享码（推荐） <a class="header-anchor" href="#方式-1-粘贴分享码-推荐" aria-label="Permalink to &quot;方式 ①：粘贴分享码（推荐）&quot;">​</a></h2><p>分享码是一串以 <code>AFMOD1:</code> 开头的文本，别人发给你，你粘进游戏就装好了。</p><h3 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h3><ol><li>从朋友那里拿到分享码（聊天消息里的一长串文本）。</li><li>打开游戏 → 点悬浮窗「小u」→ 切到「<strong>参数</strong>」页。</li><li>找到「<strong>粘贴导入分享码</strong>」按钮，点它。</li><li>把分享码粘贴进去 → 确认。</li><li><strong>完全退出游戏，重新启动</strong>。</li></ol><h3 id="怎么确认装上了" tabindex="-1">怎么确认装上了 <a class="header-anchor" href="#怎么确认装上了" aria-label="Permalink to &quot;怎么确认装上了&quot;">​</a></h3><p>重开游戏后 → 「Mod」页，应该能看到新出现的这个 Mod，带作者和版本号。</p><h3 id="分享码是什么" tabindex="-1">分享码是什么 <a class="header-anchor" href="#分享码是什么" aria-label="Permalink to &quot;分享码是什么&quot;">​</a></h3><p>它是把 <code>mod.json</code> 的内容做了 Base64 编码的结果：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mod.json 的内容</span></span>
<span class="line"><span>      ↓ UTF-8 编码</span></span>
<span class="line"><span>      ↓ Base64 编码</span></span>
<span class="line"><span>AFMOD1:ew0KICAibW9kTmFtZSI6ICIuLi4i...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">为什么用分享码而不是直接发文件</p><p>因为手机之间传文件要经过文件管理器、要找到目录、要确认权限，门槛高。而分享码就是一段文本，<strong>能从任何聊天软件直接粘贴</strong>，对不熟悉手机文件系统的人最友好。</p></div><h3 id="分享码太长被截断怎么办" tabindex="-1">分享码太长被截断怎么办 <a class="header-anchor" href="#分享码太长被截断怎么办" aria-label="Permalink to &quot;分享码太长被截断怎么办&quot;">​</a></h3><p>聊天软件有时会把长文本截断。如果导入失败：</p><ol><li><strong>让对方重新发一次</strong>，或者发成 <code>.txt</code> 文件（框架也支持把码存成文件）。</li><li>使用更稳的方式：让对方把 Mod 发到 <a href="/AtlanticFleetSite/docs/repo/start">在线仓库</a>，你去网页上复制。</li></ol><hr><h2 id="方式-2-从网页下载-放进目录" tabindex="-1">方式 ②：从网页下载，放进目录 <a class="header-anchor" href="#方式-2-从网页下载-放进目录" aria-label="Permalink to &quot;方式 ②：从网页下载，放进目录&quot;">​</a></h2><p>适合想要文件留底、或者要装好几个 Mod 的情况。</p><h3 id="步骤-1" tabindex="-1">步骤 <a class="header-anchor" href="#步骤-1" aria-label="Permalink to &quot;步骤&quot;">​</a></h3><ol><li>打开 <a href="https://atlanticfleet.asia/mods/" target="_blank" rel="noreferrer">Mod 仓库</a>，找到你要的 Mod。</li><li>点「<strong>下载</strong>」，得到一个 <code>xxx.json</code> 文件。</li><li>用文件管理器（推荐 MT管理器）进入：<div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Android/data/&lt;游戏包名&gt;/files/mods/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div></li><li><strong>新建一个子文件夹</strong>（名字随意，比如用 Mod 的名字）。</li><li>把下载的 <code>xxx.json</code> 放进这个子文件夹，<strong>改名为 <code>mod.json</code></strong>。</li><li><strong>完全退出游戏，重新启动</strong>。</li></ol><p>正确的目录结构：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mods/</span></span>
<span class="line"><span>└── 我下载的Mod/          ← 自己新建的文件夹</span></span>
<span class="line"><span>    └── mod.json          ← 下载的 json 改名成这个</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">两个最容易错的地方</p><ol><li><strong>放进子文件夹</strong>，不要直接丢在 <code>mods/</code> 根目录。</li><li><strong>文件名必须是 <code>mod.json</code></strong>，不能是 <code>xxx.json</code> 或 <code>mod.json.txt</code>。</li></ol><p>如果重开游戏后在「Mod」页没看到它，先检查这两点。</p></div><hr><h2 id="方式-3-手动新建-自己做-mod-时" tabindex="-1">方式 ③：手动新建（自己做 Mod 时） <a class="header-anchor" href="#方式-3-手动新建-自己做-mod-时" aria-label="Permalink to &quot;方式 ③：手动新建（自己做 Mod 时）&quot;">​</a></h2><p>如果你想自己写一个 Mod，这是最直接的方式。</p><h3 id="步骤-2" tabindex="-1">步骤 <a class="header-anchor" href="#步骤-2" aria-label="Permalink to &quot;步骤&quot;">​</a></h3><ol><li>进入 <code>mods/</code> 目录，新建文件夹，比如 <code>我的测试Mod</code>。</li><li>里面新建 <code>mod.json</code>，写入最小内容：</li></ol><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;modName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;我的测试Mod&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;author&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你的名字&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;version&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;combat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;gun&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;damageMul&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.5</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><ol start="3"><li>完全退出游戏，重新启动。</li><li>进「Mod」页确认出现了；进「状态」页确认 <code>combat.gun.damageMul</code> 显示为偏离原版。</li></ol><p>完整字段规范见 <a href="/AtlanticFleetSite/docs/dev/mod-json">mod.json 完整规范</a>。</p><hr><h2 id="装完之后" tabindex="-1">装完之后 <a class="header-anchor" href="#装完之后" aria-label="Permalink to &quot;装完之后&quot;">​</a></h2><h3 id="确认列表" tabindex="-1">确认列表 <a class="header-anchor" href="#确认列表" aria-label="Permalink to &quot;确认列表&quot;">​</a></h3><p>打开面板 → 「Mod」页，逐项检查：</p><ul><li>✅ 你装的 Mod <strong>出现在列表里</strong></li><li>✅ 显示正确的<strong>作者</strong>和<strong>版本</strong></li><li>✅ 顶部<strong>没有冲突告警</strong>（如果有，看 <a href="/AtlanticFleetSite/docs/use/conflicts">Mod 冲突排查</a>）</li></ul><h3 id="想让改动生效" tabindex="-1">想让改动生效 <a class="header-anchor" href="#想让改动生效" aria-label="Permalink to &quot;想让改动生效&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">必须重开游戏</p><p>Mod 是<strong>在游戏启动时读取一次</strong>的。运行中改文件、装新 Mod 都不会即时生效。</p><p>所以流程永远是：<strong>装好 / 改好 → 完全退出 → 重开</strong>。</p><p>「完全退出」指的是从后台任务里划掉，不是按 Home 键。</p></div><h3 id="装了好几个-mod-谁生效" tabindex="-1">装了好几个 Mod，谁生效 <a class="header-anchor" href="#装了好几个-mod-谁生效" aria-label="Permalink to &quot;装了好几个 Mod，谁生效&quot;">​</a></h3><p>如果在两个 Mod 里改了<strong>同一个参数</strong>，后加载的会覆盖先加载的。</p><ul><li>框架会在「日志」页记一条<strong>告警</strong>，写明是哪两个 Mod 冲突。</li><li>想控制谁覆盖谁，用 <code>priority</code> 字段（数值小的先加载）。详见 <a href="/AtlanticFleetSite/docs/use/conflicts">多 Mod 叠加</a>。</li></ul><h3 id="不想要了" tabindex="-1">不想要了 <a class="header-anchor" href="#不想要了" aria-label="Permalink to &quot;不想要了&quot;">​</a></h3><p>不用删文件。「Mod」页里可以<strong>禁用</strong>（保留文件，写一个 <code>_disabled.txt</code> 标记）或<strong>删除</strong>（两段确认，真的删掉文件夹）。</p><p>详见 <a href="/AtlanticFleetSite/docs/use/mods-page">Mod 页：管理已装 Mod</a>。</p>`,47)])])}const b=a(t,[["render",l]]);export{u as __pageData,b as default};
